SELECT a INTO OUTFILE '/tmp/f' CHARACTER SET utf8mb4 FROM t
-- case
SELECT a FROM t INTO OUTFILE '/tmp/f' CHARACTER SET utf8mb4 FIELDS TERMINATED BY ','
-- case
SELECT * FROM t1, t2 FOR SHARE OF t1 NOWAIT FOR UPDATE OF t2 SKIP LOCKED
-- case
SELECT * FROM t INTO @a FOR UPDATE
-- case
SELECT * FROM (VALUES ROW(1, 2), ROW(3, 4)) AS v (c1, c2)
-- case
LOAD DATA CONCURRENT INFILE '/tmp/f' IGNORE INTO TABLE t
-- case
LOAD DATA INFILE '/tmp/f' INTO TABLE t PARTITION (p0) CHARACTER SET utf8mb4
-- case
LOAD DATA INFILE '/tmp/f' INTO TABLE t COLUMNS TERMINATED BY ',' IGNORE 2 ROWS
